import { getSupabaseAdmin } from "./supabase.js";
import { humanBlock, splitNoteZones } from "../../../shared/brainNoteZones.js";

// ─── Second Brain notes (brain_notes, migración v47) ─────────────────────
// Markdown notes generated by the system with [[wikilinks]]. Each note has
// generated sections (rebuilt on every emit) and protected blocks written by
// humans or agents that survive regeneration verbatim — see
// harness/BRAIN_NOTES_SPEC.md.

export type BrainNoteInput = {
  workspaceId: string;
  slug: string;
  title: string;
  bodyMd: string;
  links?: string[];
  entityType?: string;
  entityId?: string;
  source?: "system" | "human" | "agent";
};

export type BrainNote = BrainNoteInput & {
  id: string;
  createdAt?: string;
  updatedAt?: string;
};

const HUMAN_BLOCK_RE = /<!--\s*human\s*-->[\s\S]*?<!--\s*\/human\s*-->/gi;
const AGENT_BLOCK_RE = /<!--\s*agent\s*-->[\s\S]*?<!--\s*\/agent\s*-->/gi;

/** Pull the `<!-- human -->` / `<!-- agent -->` blocks out of a note body, in
 *  the order they appear, so they can be re-appended after regeneration. */
export function extractProtectedBlocks(body: string | null | undefined): string {
  if (!body) return "";
  const blocks: string[] = [];
  for (const match of body.matchAll(HUMAN_BLOCK_RE)) blocks.push(match[0]);
  for (const match of body.matchAll(AGENT_BLOCK_RE)) blocks.push(match[0]);
  return blocks.join("\n\n");
}

/** Regeneration rule: generated content is rebuilt from scratch, but any
 *  `<!-- human -->…<!-- /human -->` or `<!-- agent -->…<!-- /agent -->` block
 *  already in the note is preserved verbatim at the end of the new body. */
export function protectHumanBlocks(existing: string | null | undefined, nextBody: string): string {
  const protectedBlocks = extractProtectedBlocks(existing);
  if (!protectedBlocks) return nextBody;
  return `${nextBody}\n\n${protectedBlocks}`;
}

export function slugifyPart(name: string): string {
  const slug = name.toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return slug || "sin-nombre";
}

function rowToNote(row: any): BrainNote {
  return {
    id: row.id,
    workspaceId: row.workspace_id,
    slug: row.slug,
    title: row.title,
    bodyMd: row.body_md,
    links: row.links || [],
    entityType: row.entity_type || undefined,
    entityId: row.entity_id || undefined,
    source: row.source,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/** Idempotent upsert by (workspace_id, slug). Protected blocks from the
 *  existing body are carried into the new one. Returns null without Supabase
 *  (local dev fallback) — emitters treat it as best-effort.
 *
 *  Writes go through the SERVICE client on purpose: brain_notes revokes
 *  INSERT/UPDATE/DELETE for `authenticated` (v47 — browsers read only), so an
 *  emitter running inside a request with a user Bearer (getSupabase() returns
 *  the RLS-scoped client) failed silently and the vault stayed empty.
 *  `protect: false` writes the body verbatim — for zone-level merges that
 *  already carry their own protected blocks. */
export async function upsertBrainNote(input: BrainNoteInput, opts?: { protect?: boolean }): Promise<BrainNote | null> {
  const sb = getSupabaseAdmin();
  if (!sb) return null;
  try {
    const { data: existing } = await sb.from("brain_notes")
      .select("id, body_md, source")
      .eq("workspace_id", input.workspaceId)
      .eq("slug", input.slug)
      .maybeSingle();
    const bodyMd = opts?.protect === false
      ? input.bodyMd
      : protectHumanBlocks(existing?.body_md, input.bodyMd);
    const { data, error } = await sb.from("brain_notes")
      .upsert({
        workspace_id: input.workspaceId,
        slug: input.slug,
        title: input.title,
        body_md: bodyMd,
        links: input.links || [],
        entity_type: input.entityType || null,
        entity_id: input.entityId || null,
        source: input.source || "system",
      }, { onConflict: "workspace_id,slug" })
      .select("*")
      .single();
    if (error) throw error;
    return data ? rowToNote(data) : null;
  } catch (error) {
    console.warn("[brainNotes] upsert failed:", (error as Error).message);
    return null;
  }
}

export async function getBrainNote(workspaceId: string, slug: string): Promise<BrainNote | null> {
  const sb = getSupabaseAdmin();
  if (!sb) return null;
  const { data, error } = await sb.from("brain_notes")
    .select("*")
    .eq("workspace_id", workspaceId)
    .eq("slug", slug)
    .maybeSingle();
  if (error || !data) return null;
  return rowToNote(data);
}

export async function listBrainNotes(
  workspaceId: string,
  opts?: { limit?: number; offset?: number; entityType?: string },
): Promise<BrainNote[]> {
  const sb = getSupabaseAdmin();
  if (!sb) return [];
  let query = sb.from("brain_notes")
    .select("*")
    .eq("workspace_id", workspaceId)
    .order("updated_at", { ascending: false })
    .range(opts?.offset || 0, (opts?.offset || 0) + (opts?.limit || 50) - 1);
  if (opts?.entityType) query = query.eq("entity_type", opts.entityType);
  const { data, error } = await query;
  if (error) return [];
  return (data || []).map(rowToNote);
}

/** Free-text search across title + body. The pg_trgm GIN index (v47) keeps
 *  this fast; server-side emitters use the service client so RLS still
 *  resolves through has_workspace_role for direct client reads. */
export async function searchBrainNotes(workspaceId: string, queryText: string, limit = 20): Promise<BrainNote[]> {
  const sb = getSupabaseAdmin();
  if (!sb) return [];
  const needle = queryText.replace(/[%,]/g, " ").trim();
  if (!needle) return [];
  const { data, error } = await sb.from("brain_notes")
    .select("*")
    .eq("workspace_id", workspaceId)
    .or(`title.ilike.%${needle}%,body_md.ilike.%${needle}%`)
    .order("updated_at", { ascending: false })
    .limit(limit);
  if (error) return [];
  return (data || []).map(rowToNote);
}

// ─── Emitters (server-side, idempotent by slug) ───────────────────────────

function wikilink(slug: string): string {
  return `[[${slug}]]`;
}

type BrandLike = {
  id: string;
  workspaceId: string;
  name: string;
  designSystemTemplateId?: string;
  crmBrandId?: string;
  styleFingerprint?: string;
};

export function brandNoteSlug(brandName: string): string {
  return `marca-${slugifyPart(brandName)}`;
}

/** Fired when a brand (and therefore its container files) exists. */
export async function emitBrandCreatedNote(
  brand: BrandLike,
  containers: { plantillasTemplateId?: string; communicationTemplateId?: string },
): Promise<void> {
  const slug = brandNoteSlug(brand.name);
  const dsSlug = `ds-${slugifyPart(brand.name)}`;
  const plantillasSlug = `plantillas-${slugifyPart(brand.name)}`;
  const comunicacionSlug = `comunicacion-${slugifyPart(brand.name)}`;
  await upsertBrainNote({
    workspaceId: brand.workspaceId,
    slug,
    title: `Marca: ${brand.name}`,
    bodyMd: [
      `<!-- generated -->`,
      `# Marca: ${brand.name}`,
      ``,
      `- brand_guideline: \`${brand.id}\``,
      `- CRM brand: \`${brand.crmBrandId || "sin vincular"}\``,
      `- Design System: ${brand.designSystemTemplateId ? wikilink(dsSlug) : "pendiente"} (\`${brand.designSystemTemplateId || "—"}\`)`,
      `- Plantillas: ${containers.plantillasTemplateId ? wikilink(plantillasSlug) : "pendiente"} (\`${containers.plantillasTemplateId || "—"}\`)`,
      `- Comunicación: ${containers.communicationTemplateId ? wikilink(comunicacionSlug) : "pendiente"} (\`${containers.communicationTemplateId || "—"}\`)`,
      `- Fingerprint: \`${brand.styleFingerprint || "—"}\``,
      `<!-- /generated -->`,
    ].join("\n"),
    links: [dsSlug, plantillasSlug, comunicacionSlug],
    entityType: "brand",
    entityId: brand.id,
    source: "system",
  });
}

/** Fired when design artifacts are published into the brand's DS. */
export async function emitDsPublishedNote(
  brand: BrandLike,
  summary: { colors?: number; fonts?: number; fingerprint?: string; source?: string },
): Promise<void> {
  const slug = `ds-${slugifyPart(brand.name)}`;
  await upsertBrainNote({
    workspaceId: brand.workspaceId,
    slug,
    title: `Design System: ${brand.name}`,
    bodyMd: [
      `<!-- generated -->`,
      `# Design System: ${brand.name}`,
      ``,
      `- Marca: ${wikilink(brandNoteSlug(brand.name))}`,
      `- Tokens: ${summary.colors ?? 0} colores, ${summary.fonts ?? 0} tipografías`,
      `- Fingerprint: \`${summary.fingerprint || brand.styleFingerprint || "—"}\``,
      `- Origen: ${summary.source || "desconocido"}`,
      `<!-- /generated -->`,
    ].join("\n"),
    links: [brandNoteSlug(brand.name)],
    entityType: "design_system",
    entityId: brand.id,
    source: "system",
  });
}

