// ─── Vault vivo: una nota por entidad (spec v1, extendida) ────────────────
// Cada rama de la marca tiene su nota: generated se reconstruye SIEMPRE desde
// las tablas fuente al regenerar; human/agent sobreviven (protectHumanBlocks).

export function dsNoteSlug(brandName: string): string { return `ds-${slugifyPart(brandName)}`; }
export function plantillasNoteSlug(brandName: string): string { return `plantillas-${slugifyPart(brandName)}`; }
export function estrategiaNoteSlug(brandName: string): string { return `estrategia-${slugifyPart(brandName)}`; }
export function copywritingNoteSlug(brandName: string): string { return `copywriting-${slugifyPart(brandName)}`; }
export function crmNoteSlug(brandName: string): string { return `crm-${slugifyPart(brandName)}`; }
export function personaNoteSlug(brandName: string, index: number): string { return `persona-${slugifyPart(brandName)}-${index}`; }
export function archivoNoteSlug(templateId: string): string { return `archivo-${templateId}`; }
export function archivosNoteSlug(brandName: string): string { return `archivos-${slugifyPart(brandName)}`; }

const DAY_MS = 86_400_000;

function fmtDay(value?: string | null): string {
  const ms = Date.parse(value || "");
  return Number.isFinite(ms) ? new Date(ms).toISOString().slice(0, 10) : "—";
}

function daysSince(value?: string | null): number | null {
  const ms = Date.parse(value || "");
  return Number.isFinite(ms) ? Math.floor((Date.now() - ms) / DAY_MS) : null;
}

function money(value: number, currency?: string | null): string {
  try {
    return new Intl.NumberFormat("es", { style: "currency", currency: (currency || "USD").toUpperCase(), maximumFractionDigits: 0 }).format(value);
  } catch { return `${value} ${currency || ""}`.trim(); }
}

/** Tolerant DTCG read of tokens_json (same idea as extractTokenDigest in
 *  brandGraph.ts, kept local to avoid a brainNotes→brandGraph cycle). */
function summarizeTokensLocal(tokensJson: string | null | undefined): {
  colors: string[]; fonts: string[];
  counts: { color: number; typography: number; spacing: number; radius: number; shadow: number };
} {
  const counts = { color: 0, typography: 0, spacing: 0, radius: 0, shadow: 0 };
  const colors: string[] = [];
  const fonts: string[] = [];
  const visit = (node: unknown, path: string): void => {
    if (!node || typeof node !== "object") return;
    const record = node as Record<string, unknown>;
    const value = record.$value;
    if (typeof value === "string" && value) {
      if (/^(#[0-9a-f]{3,8}|rgba?\(|hsla?\()/i.test(value) && /colou?r|palette|accent|primary|secondary|brand|background|surface/i.test(path)) {
        counts.color += 1;
        if (colors.length < 12) colors.push(value);
      } else if (/font|typograph|family|typeface/i.test(path)) {
        counts.typography += 1;
        const family = typeof value === "object" ? String((value as any)?.fontFamily || value) : value.replace(/["']/g, "");
        if (fonts.length < 8) fonts.push(family);
      } else if (/spac|gap|mARGIN/i.test(path)) counts.spacing += 1;
      else if (/radius|round/i.test(path)) counts.radius += 1;
      else if (/shadow|elevat/i.test(path)) counts.shadow += 1;
    }
    for (const [key, child] of Object.entries(record)) visit(child, `${path}.${key}`);
  };
  try { visit(JSON.parse(tokensJson || "null"), ""); } catch { /* tokens ausentes o malformados */ }
  return { colors: [...new Set(colors)], fonts: [...new Set(fonts)], counts };
}

function parsePersonas(strategyJson: string | null | undefined): Array<{ name: string; description?: string }> {
  try {
    const doc = JSON.parse(strategyJson || "null");
    const list = doc?.audience?.personas;
    return Array.isArray(list)
      ? list.filter((p: any) => p && String(p?.name || "").trim()).slice(0, 12)
      : [];
  } catch { return []; }
}

/** Raw rows the brand-scoped emitters need — loaded once, shared by all. */
export type BrandVaultInputs = {
  workspaceId: string;
  brand: {
    id: string; name: string;
    relationshipStatus?: string; accountHealth?: string; priority?: string;
    lastContactedAt?: string | null;
  };
  style: {
    id: string; name: string;
    designSystemTemplateId: string | null;
    tokensJson: string | null;
    strategyJson: string | null;
    styleFingerprint: string | null;
  } | null;
  containers: {
    ds: string | null; plantillas: string | null; communication: string | null;
    plantillasFrames: Array<{ id: string; name: string }>;
  };
  deals: Array<{ id: string; title: string; stage: string; value: number; currency: string; probability: number; nextStepNote?: string | null; nextStepDate?: string | null }>;
  contacts: Array<{ id: string; name: string; jobTitle?: string | null; status?: string | null }>;
  interactions: Array<{ interactionType: string; notes?: string | null; interactionDate: string }>;
  interactionCount: number;
  metaFileCount: number;
  /** Latest files under the brand — the index of the Archivos branch note. */
  metaFiles: Array<{ templateId: string; name: string; campaign: string; category: string; updatedAt: string | null }>;
};

export async function loadBrandVaultInputs(workspaceId: string, brandId: string): Promise<BrandVaultInputs | null> {
  const sb = getSupabaseAdmin();
  if (!sb) return null;
  const { data: brand } = await sb.from("brands")
    .select("id, name, relationship_status, account_health, crm_priority, last_contacted_at")
    .eq("workspace_id", workspaceId).eq("id", brandId).maybeSingle();
  if (!brand) return null;

  // The style (brand_guidelines) linked to this CRM brand; the name fallback
  // covers rows the backfill hasn't linked yet (same rule as the graph).
  const { data: styleRows } = await sb.from("brand_guidelines")
    .select("id, name, data, design_system_template_id, crm_brand_id, strategy_json")
    .eq("workspace_id", workspaceId);
  const style = (styleRows || []).find((s: any) =>
    s.crm_brand_id === brand.id
    || String(s.name || "").trim().toLowerCase() === String(brand.name || "").trim().toLowerCase()
  ) || null;

  const { data: containerRows } = await sb.from("templates")
    .select("id, name, brandId:data->>brandId, brand_container_kind, frames:data->frames")
    .eq("workspace_id", workspaceId)
    .is("deleted_at", null);
  const containers = {
    ds: null as string | null,
    plantillas: null as string | null,
    communication: null as string | null,
    plantillasFrames: [] as Array<{ id: string; name: string }>,
  };
  for (const row of containerRows || []) {
    if (row.brandId !== brand.id || !row.brand_container_kind) continue;
    const kind = row.brand_container_kind as "ds" | "plantillas" | "communication";
    if (kind === "ds" && !containers.ds) containers.ds = row.id;
    if (kind === "plantillas" && !containers.plantillas) {
      containers.plantillas = row.id;
      const frames = Array.isArray(row.frames) ? row.frames : [];
      containers.plantillasFrames = frames.slice(0, 50).map((f: any) => ({
        id: String(f?.id || ""), name: String(f?.name || "sin nombre"),
      }));
    }
    if (kind === "communication" && !containers.communication) containers.communication = row.id;
  }

  const [dealsResult, contactsResult, latestInteractions, interactionCount, metaCount, metaRows] = await Promise.all([
    sb.from("crm_deals")
      .select("id, title, stage, value, currency, probability, next_step_note, next_step_date, updated_at")
      .eq("workspace_id", workspaceId).eq("brand_id", brand.id)
      .order("updated_at", { ascending: false }).limit(100),
    sb.from("crm_contacts")
      .select("id, first_name, last_name, job_title, status")
      .eq("workspace_id", workspaceId).eq("brand_id", brand.id)
      .order("first_name").limit(100),
    sb.from("crm_interactions")
      .select("interaction_type, notes, interaction_date")
      .eq("workspace_id", workspaceId).eq("brand_id", brand.id)
      .order("interaction_date", { ascending: false }).limit(8),
    sb.from("crm_interactions")
      .select("id", { count: "exact", head: true })
      .eq("workspace_id", workspaceId).eq("brand_id", brand.id),
    sb.from("design_file_meta")
      .select("template_id", { count: "exact", head: true })
      .eq("workspace_id", workspaceId).eq("brand_id", brand.id),
    sb.from("design_file_meta")
      .select("template_id, campaign, category, updated_at")
      .eq("workspace_id", workspaceId).eq("brand_id", brand.id)
      .order("updated_at", { ascending: false }).limit(100),
  ]);

  // Names for the Archivos index: containerRows already carries every
  // non-deleted template of the workspace, so no extra query is needed.
  const nameByTemplate = new Map<string, string>(
    (containerRows || []).map((row: any) => [row.id, String(row.name || "")]),
  );

  return {
    workspaceId,
    brand: {
      id: brand.id, name: brand.name,
      relationshipStatus: brand.relationship_status || undefined,
      accountHealth: brand.account_health || undefined,
      priority: brand.crm_priority || undefined,
      lastContactedAt: brand.last_contacted_at || null,
    },
    style: style ? {
      id: style.id, name: style.name,
      designSystemTemplateId: style.design_system_template_id || null,
      tokensJson: style.data?.tokensJson ?? null,
      strategyJson: style.strategy_json ?? null,
      styleFingerprint: style.data?.styleFingerprint ?? null,
    } : null,
    containers,
    deals: (dealsResult.data || []).map((d: any) => ({
      id: d.id, title: d.title || d.id, stage: d.stage || "discovery",
      value: Number(d.value || 0), currency: d.currency || "USD",
      probability: Number(d.probability || 0),
      nextStepNote: d.next_step_note ?? null, nextStepDate: d.next_step_date ?? null,
    })),
    contacts: (contactsResult.data || []).map((c: any) => ({
      id: c.id,
      name: [c.first_name, c.last_name].filter(Boolean).join(" ") || c.id,
      jobTitle: c.job_title ?? null, status: c.status ?? null,
    })),
    interactions: (latestInteractions.data || []).map((i: any) => ({
      interactionType: i.interaction_type || "otro",
      notes: i.notes ?? null, interactionDate: i.interaction_date || "",
    })),
    interactionCount: interactionCount.count ?? (latestInteractions.data || []).length,
    metaFileCount: metaCount.count ?? 0,
    metaFiles: (metaRows.data || []).map((m: any) => ({
      templateId: m.template_id,
      name: nameByTemplate.get(m.template_id) || m.template_id,
      campaign: m.campaign || "", category: m.category || "",
      updatedAt: m.updated_at ?? null,
    })),
  };
}

const STAGE_LABELS: Record<string, string> = {
  discovery: "descubrimiento", proposal: "propuesta", negotiation: "negociación",
  approved: "aprobado", in_production: "en producción", review: "revisión",
  ready: "listo", delivered: "entregado", lost: "perdido",
};

export async function emitMarcaNote(inputs: BrandVaultInputs): Promise<BrainNote | null> {
  const { brand } = inputs;
  const open = inputs.deals.filter(d => !"delivered,lost".includes(d.stage));
  const pipeline = open.reduce((total, d) => total + d.value, 0);
  const currency = open[0]?.currency || inputs.deals[0]?.currency || "USD";
  const since = daysSince(brand.lastContactedAt);
  const body = [
    `<!-- generated -->`,
    `# Marca: ${brand.name}`,
    ``,
    `## Resumen vivo`,
    `- Salud: ${brand.accountHealth || "active"} · Prioridad: ${brand.priority || "medium"} · Relación: ${brand.relationshipStatus || "lead"}`,
    `- Último contacto: ${fmtDay(brand.lastContactedAt)}${since === null ? "" : ` (hace ${since} días)`}`,
    `- Deals: ${open.length}/${inputs.deals.length} abiertos · Pipeline ${money(pipeline, currency)}`,
    `- Personas: ${inputs.contacts.length} · Interacciones: ${inputs.interactionCount}`,
    `- Archivos bajo la marca: ${inputs.metaFileCount} · Plantillas curadas: ${inputs.containers.plantillasFrames.length}`,
    ``,
    `## Ramas del second brain`,
    `- Design System: [[${dsNoteSlug(brand.name)}]]${inputs.containers.ds || inputs.style?.designSystemTemplateId ? "" : " (pendiente)"}`,
    `- Plantillas: [[${plantillasNoteSlug(brand.name)}]]`,
    `- Archivos: [[${archivosNoteSlug(brand.name)}]] (${inputs.metaFileCount} fichas)`,
    `- CRM: [[${crmNoteSlug(brand.name)}]]`,
    `- Estrategia de Marca: [[${estrategiaNoteSlug(brand.name)}]]`,
    `- Copywriting: [[${copywritingNoteSlug(brand.name)}]]`,
    `<!-- /generated -->`,
  ].join("\n");
  return upsertBrainNote({
    workspaceId: inputs.workspaceId,
    slug: brandNoteSlug(brand.name),
    title: `Marca: ${brand.name}`,
    bodyMd: body,
    links: [dsNoteSlug(brand.name), plantillasNoteSlug(brand.name), archivosNoteSlug(brand.name), crmNoteSlug(brand.name), estrategiaNoteSlug(brand.name), copywritingNoteSlug(brand.name)],
    entityType: "brand", entityId: brand.id, source: "system",
  });
}

export async function emitCrmNote(inputs: BrandVaultInputs): Promise<BrainNote | null> {
  const lines: string[] = [
    `<!-- generated -->`,
    `# CRM: ${inputs.brand.name}`,
    ``,
    `## Deals`,
  ];
  if (!inputs.deals.length) lines.push("- Sin deals todavía.");
  for (const deal of inputs.deals.slice(0, 20)) {
    const next = deal.nextStepDate
      ? ` · próximo paso ${fmtDay(deal.nextStepDate)}${deal.nextStepNote ? `: ${deal.nextStepNote}` : ""}`
      : "";
    lines.push(`- **${deal.title}** — ${STAGE_LABELS[deal.stage] || deal.stage} · ${money(deal.value, deal.currency)} · prob. ${deal.probability}%${next}`);
  }
  lines.push(``, `## Personas (${inputs.contacts.length})`);
  for (const contact of inputs.contacts.slice(0, 15)) {
    lines.push(`- ${contact.name}${contact.jobTitle ? ` — ${contact.jobTitle}` : ""}${contact.status ? ` (${contact.status})` : ""}`);
  }
  lines.push(``, `## Últimas interacciones`);
  if (!inputs.interactions.length) lines.push("- Sin interacciones registradas.");
  for (const interaction of inputs.interactions) {
    lines.push(`- ${fmtDay(interaction.interactionDate)} · ${interaction.interactionType}${interaction.notes ? ` — ${String(interaction.notes).slice(0, 140)}` : ""}`);
  }
  lines.push(`<!-- /generated -->`);
  return upsertBrainNote({
    workspaceId: inputs.workspaceId,
    slug: crmNoteSlug(inputs.brand.name),
    title: `CRM: ${inputs.brand.name}`,
    bodyMd: lines.join("\n"),
    links: [brandNoteSlug(inputs.brand.name)],
    entityType: "crm", entityId: inputs.brand.id, source: "system",
  });
}

export async function emitDsNote(inputs: BrandVaultInputs): Promise<BrainNote | null> {
  const brand = inputs.brand;
  const tokens = summarizeTokensLocal(inputs.style?.tokensJson);
  const lines: string[] = [`<!-- generated -->`, `# Design System: ${brand.name}`, ``];
  if (!inputs.style) {
    lines.push(`- Sin Design System todavía: se crea junto con la marca (una marca = un DS).`);
  } else {
    lines.push(`## Paleta (${tokens.counts.color} tokens)`);
    lines.push(...(tokens.colors.length
      ? tokens.colors.map(c => `- ██ \`${c}\``)
      : ["- Sin tokens de color aún."]));
    lines.push(``, `## Tipografías`);
    lines.push(...(tokens.fonts.length
      ? tokens.fonts.map(f => `- ${f}`)
      : ["- Sin tipografías definidas."]));
    lines.push(
      ``,
      `## Tokens`,
      `- Spacing: ${tokens.counts.spacing} · Radius: ${tokens.counts.radius} · Sombras: ${tokens.counts.shadow} · Estilos tipográficos: ${tokens.counts.typography}`,
    );
    if (inputs.style.styleFingerprint) lines.push(`- Fingerprint: \`${String(inputs.style.styleFingerprint).slice(0, 24)}…\``);
    if (inputs.containers.ds) lines.push(`- Archivo contenedor: [[${archivoNoteSlug(inputs.containers.ds)}]]`);
  }
  lines.push(`<!-- /generated -->`);
  return upsertBrainNote({
    workspaceId: inputs.workspaceId,
    slug: dsNoteSlug(brand.name),
    title: `Design System: ${brand.name}`,
    bodyMd: lines.join("\n"),
    links: [brandNoteSlug(brand.name)],
    entityType: "design_system", entityId: inputs.style?.id || brand.id, source: "system",
  });
}

export async function emitPlantillasVaultNote(inputs: BrandVaultInputs): Promise<BrainNote | null> {
  const frames = inputs.containers.plantillasFrames;
  const lines: string[] = [
    `<!-- generated -->`,
    `# Plantillas: ${inputs.brand.name}`,
    ``,
    `- Frames curados: ${frames.length}${inputs.containers.plantillas ? "" : " (contenedor aún no creado)"}`,
    ``,
  ];
  lines.push(...(frames.length
    ? frames.map((frame, i) => `${i + 1}. ${frame.name}`)
    : ["- Curá tu primera plantilla: elegí un frame de un archivo de esta marca y guardalo como plantilla."]));
  lines.push(`<!-- /generated -->`);
  return upsertBrainNote({
    workspaceId: inputs.workspaceId,
    slug: plantillasNoteSlug(inputs.brand.name),
    title: `Plantillas: ${inputs.brand.name}`,
    bodyMd: lines.join("\n"),
    links: [brandNoteSlug(inputs.brand.name)],
    entityType: "plantillas", entityId: inputs.brand.id, source: "system",
  });
}

/** The Archivos branch: index of every file under the brand, one wikilink
 *  per file note (archivo-<templateId>) so the branch reads like an
 *  Obsidian MOC (map of content). */
export async function emitArchivosNote(inputs: BrandVaultInputs): Promise<BrainNote | null> {
  const { brand } = inputs;
  const lines: string[] = [
    `<!-- generated -->`,
    `# Archivos: ${brand.name}`,
    ``,
    `- Fichas bajo la marca: ${inputs.metaFileCount}${inputs.metaFiles.length < inputs.metaFileCount ? ` (índice con las últimas ${inputs.metaFiles.length})` : ""}`,
    ``,
    `## Índice`,
    ...(inputs.metaFiles.length
      ? inputs.metaFiles.map((f) => `- ${f.campaign ? `\`${f.campaign}\` · ` : ""}[[${archivoNoteSlug(f.templateId)}|${f.name}]]`)
      : ["- Todavía no hay archivos bajo esta marca — se agregan solos al asignar la marca a un diseño."]),
    `<!-- /generated -->`,
  ];
  return upsertBrainNote({
    workspaceId: inputs.workspaceId,
    slug: archivosNoteSlug(brand.name),
    title: `Archivos: ${brand.name}`,
    bodyMd: lines.join("\n"),
    links: [brandNoteSlug(brand.name), ...inputs.metaFiles.map((f) => archivoNoteSlug(f.templateId))],
    entityType: "archivos", entityId: brand.id, source: "system",
  });
}

export async function emitEstrategiaNote(inputs: BrandVaultInputs): Promise<BrainNote | null> {
  const brand = inputs.brand;
  let strategy: any = {};
  try { strategy = JSON.parse(inputs.style?.strategyJson || "null") || {}; } catch { /* strategy ausente */ }
  const essence = strategy.essence || {};
  const tone = strategy.tone || {};
  const axes = tone.axes || {};
  const voice = strategy.voice || {};
  const advanced = strategy.advanced || {};
  const personas = parsePersonas(inputs.style?.strategyJson);
  const lines: string[] = [`<!-- generated -->`, `# Estrategia de Marca: ${brand.name}`, ``];
  if (!inputs.style?.strategyJson) {
    lines.push(`- Sin canvas de estrategia todavía. Se llena en Design Systems → ${brand.name} → Estrategia de Marca (Brand Strategy Canvas).`);
  } else {
    lines.push(`## Esencia`);
    if (essence.mission) lines.push(`- Misión: ${essence.mission}`);
    if (essence.vision) lines.push(`- Visión: ${essence.vision}`);
    if (Array.isArray(essence.values) && essence.values.length) lines.push(`- Valores: ${essence.values.join(", ")}`);
    if (essence.valueProposition) lines.push(`- Propuesta de valor: ${essence.valueProposition}`);
    if (essence.positioning) lines.push(`- Posicionamiento: ${essence.positioning}`);
    lines.push(``, `## Tono`);
    const axisText = Object.entries(axes)
      .filter(([, v]) => typeof v === "number")
      .map(([k, v]) => `${k} ${v}`).join(" · ");
    if (axisText) lines.push(`- Ejes: ${axisText}`);
    if (tone.person) lines.push(`- Persona gramatical: ${tone.person} · Emojis: ${tone.emojiPolicy || "sin política"}`);
    lines.push(``, `## Personas sintéticas (${personas.length})`);
    lines.push(...(personas.length
      ? personas.map((p, i) => `- [[${personaNoteSlug(brand.name, i)}]] ${p.name}${p.description ? ` — ${String(p.description).slice(0, 160)}` : ""}`)
      : ["- Ninguna definida."]));
    if (advanced.archetype) lines.push(``, `- Arquetipo: ${advanced.archetype}`);
  }
  lines.push(`<!-- /generated -->`);
  const body = lines.join("\n");
  // Legacy migration (spec v1 slug `comunicacion-*`): the first time the new
  // slug is written, carried-over human text from the old note survives —
  // protectHumanBlocks keeps it on every later regeneration.
  const slug = estrategiaNoteSlug(brand.name);
  const existing = await getBrainNote(inputs.workspaceId, slug);
  let finalBody = body;
  if (!existing) {
    const legacyBody = (await getBrainNote(inputs.workspaceId, `comunicacion-${slugifyPart(brand.name)}`))?.bodyMd || "";
    if (legacyBody) {
      const zones = splitNoteZones(legacyBody);
      const humanMd = zones.legacyFreeForm ? (zones.human || legacyBody.trim()) : zones.human;
      if (humanMd) finalBody += `\n\n${humanBlock(humanMd)}`;
    }
  }
  return upsertBrainNote({
    workspaceId: inputs.workspaceId,
    slug,
    title: `Estrategia de Marca: ${brand.name}`,
    bodyMd: finalBody,
    links: [brandNoteSlug(brand.name), ...personas.map((_, i) => personaNoteSlug(brand.name, i))],
    entityType: "strategy", entityId: inputs.style?.id || brand.id, source: "system",
  });
}

export async function emitPersonaNote(
  inputs: BrandVaultInputs, index: number, persona: { name?: string; description?: string },
): Promise<BrainNote | null> {
  const name = String(persona?.name || `Persona ${index + 1}`);
  const description = String(persona?.description || "").trim();
  const body = [
    `<!-- generated -->`,
    `# Persona sintética: ${name}`,
    ``,
    `- Marca: [[${estrategiaNoteSlug(inputs.brand.name)}]]`,
    ``,
    description || "Sin descripción todavía — se escribe en el Brand Strategy Canvas (sección Audiencia).",
    `<!-- /generated -->`,
  ].join("\n");
  return upsertBrainNote({
    workspaceId: inputs.workspaceId,
    slug: personaNoteSlug(inputs.brand.name, index),
    title: `Persona: ${name}`,
    bodyMd: body,
    links: [estrategiaNoteSlug(inputs.brand.name), brandNoteSlug(inputs.brand.name)],
    entityType: "persona", entityId: `${inputs.brand.id}:${index}`, source: "system",
  });
}

export async function emitCopywritingNote(inputs: BrandVaultInputs): Promise<BrainNote | null> {
  let strategy: any = {};
  try { strategy = JSON.parse(inputs.style?.strategyJson || "null") || {}; } catch { /* strategy ausente */ }
  const voice = strategy.voice || {};
  const sections: Array<[string, unknown]> = [
    ["Vocabulario SÍ", voice.vocabularyYes],
    ["Vocabulario NO", voice.vocabularyNo],
    ["Muletillas prohibidas", voice.bannedTells],
    ["Estructuras de hook", voice.hookStructures],
    ["Patrones de CTA", voice.ctaPatterns],
  ];
  const lines: string[] = [`<!-- generated -->`, `# Copywriting: ${inputs.brand.name}`, ``];
  if (!inputs.style?.strategyJson) {
    lines.push(`- Sin política de voz todavía: se define en el Brand Strategy Canvas (sección Voz).`);
  } else {
    for (const [label, list] of sections) {
      lines.push(`## ${label}`);
      lines.push(...(Array.isArray(list) && list.length
        ? (list as string[]).slice(0, 15).map(item => `- ${item}`)
        : ["- —"]));
    }
    const byChannel = voice.lengthByChannel && typeof voice.lengthByChannel === "object" ? voice.lengthByChannel : null;
    if (byChannel && Object.keys(byChannel).length) {
      lines.push(``, `## Largo por canal`);
      for (const [channel, value] of Object.entries(byChannel)) lines.push(`- ${channel}: ${value}`);
    }
  }
  lines.push(`<!-- /generated -->`);
  return upsertBrainNote({
    workspaceId: inputs.workspaceId,
    slug: copywritingNoteSlug(inputs.brand.name),
    title: `Copywriting: ${inputs.brand.name}`,
    bodyMd: lines.join("\n"),
    links: [brandNoteSlug(inputs.brand.name), estrategiaNoteSlug(inputs.brand.name)],
    entityType: "copywriting", entityId: inputs.style?.id || inputs.brand.id, source: "system",
  });
}

/** Emits every brand-scoped note (marca, crm, ds, plantillas, archivos,
 *  estrategia, copywriting + personas). Idempotent: regenerating never harms
 *  human or agent blocks. Returns the number of notes written. */
export async function emitBrandVault(workspaceId: string, brandId: string): Promise<{ notes: number } | null> {
  const inputs = await loadBrandVaultInputs(workspaceId, brandId);
  if (!inputs) return null;
  const emitted = await Promise.all([
    emitMarcaNote(inputs), emitCrmNote(inputs), emitDsNote(inputs),
    emitPlantillasVaultNote(inputs), emitArchivosNote(inputs),
    emitEstrategiaNote(inputs), emitCopywritingNote(inputs),
  ]);
  const personas = parsePersonas(inputs.style?.strategyJson);
  const personaNotes = await Promise.all(personas.map((persona, i) => emitPersonaNote(inputs, i, persona)));
  return { notes: emitted.filter(Boolean).length + personaNotes.filter(Boolean).length };
}

/** Replace ONLY the human zone of one note; generated and agent survive. */
export async function setHumanSection(workspaceId: string, slug: string, humanMd: string): Promise<BrainNote | null> {
  const existing = await getBrainNote(workspaceId, slug);
  if (!existing) return null;
  const zones = splitNoteZones(existing.bodyMd);
  const core = [
    zones.generated ? `<!-- generated -->\n${zones.generated}\n<!-- /generated -->` : "",
    zones.agent ? `<!-- agent -->\n${zones.agent}\n<!-- /agent -->` : "",
  ].filter(Boolean).join("\n\n");
  const block = humanBlock(humanMd);
  const bodyMd = [core, block].filter(Boolean).join("\n\n");
  return upsertBrainNote({
    workspaceId, slug, title: existing.title, bodyMd,
    links: existing.links, entityType: existing.entityType,
    entityId: existing.entityId, source: existing.source || "system",
  }, { protect: false });
}

/** Notes whose links[] point at this slug — the Obsidian backlinks panel. */
export async function getNoteBacklinks(workspaceId: string, slug: string): Promise<Array<{ slug: string; title: string }>> {
  const sb = getSupabaseAdmin();
  if (!sb) return [];
  const { data, error } = await sb.from("brain_notes")
    .select("slug, title")
    .eq("workspace_id", workspaceId)
    .contains("links", [slug])
    .order("updated_at", { ascending: false })
    .limit(50);
  if (error) return [];
  return (data || []) as Array<{ slug: string; title: string }>;
}

/** One living note per FILE (template): meta + wikilink to its brand. The
 *  manual notes_md seeds the human zone the first time — nothing is lost. */
export async function emitArchivoNoteForTemplate(templateId: string): Promise<BrainNote | null> {
  const sb = getSupabaseAdmin();
  if (!sb) return null;
  const { data: tpl } = await sb.from("templates")
    .select("id, name, workspace_id, created_at, updated_at")
    .eq("id", templateId).is("deleted_at", null).maybeSingle();
  if (!tpl) return null;
  const { data: meta } = await sb.from("design_file_meta")
    .select("brand_id, campaign, category, content_kind, asset_type, tags, cover_captured_at, notes_md")
    .eq("template_id", templateId).maybeSingle();
  let brandLink = "";
  let brandName = "";
  if (meta?.brand_id) {
    const { data: brand } = await sb.from("brands").select("name").eq("id", meta.brand_id).maybeSingle();
    if (brand) {
      brandName = brand.name;
      brandLink = `[[${brandNoteSlug(brand.name)}]]`;
    }
  }
  const tags = Array.isArray(meta?.tags)
    ? meta.tags.join(", ")
    : (typeof meta?.tags === "string" ? meta.tags : "");
  const parts: string[] = [
    `<!-- generated -->`,
    `# Archivo: ${tpl.name || tpl.id}`,
    ``,
    `- Marca: ${brandLink || "sin marca asignada"}`,
    `- Campaña: ${meta?.campaign || "—"}`,
    `- Categoría: ${meta?.category || "—"} · Tipo: ${meta?.content_kind || meta?.asset_type || "—"}`,
    ...(tags ? [`- Etiquetas: ${tags}`] : []),
    `- Creado: ${fmtDay(tpl.created_at)} · Última edición: ${fmtDay(tpl.updated_at)}`,
    `- Preview: ${meta?.cover_captured_at ? `capturado ${fmtDay(meta.cover_captured_at)}` : "pendiente de captura"}`,
    `<!-- /generated -->`,
  ];
  const zones = splitNoteZones(meta?.notes_md || "");
  const seedHuman = zones.human || (meta?.notes_md ? String(meta.notes_md).trim() : "");
  if (seedHuman) parts.push(humanBlock(seedHuman));
  return upsertBrainNote({
    workspaceId: tpl.workspace_id,
    slug: archivoNoteSlug(templateId),
    title: `Archivo: ${tpl.name || templateId}`,
    bodyMd: parts.join("\n"),
    links: brandLink ? [brandNoteSlug(brandName)] : [],
    entityType: "template", entityId: templateId, source: "system",
  });
}
